package dailyassignments;

public class Program_DoubleOfNumbers {

	public static void main(String[] args) {
		// TODO Auto-generated method stub
		 int num=1;
	        while(num<=5)
	        {
	        	int dou=num*2;
	        	System.out.println(num+" double is "+dou);
	        	num++;
	        }
	}

}
